import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

kl_div_cpp = """
torch::Tensor kl_div_cuda(torch::Tensor predictions, torch::Tensor targets);
"""

kl_div_cuda_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void kl_div_kernel(const float* p, const float* t, float* out, int total_elements) {
    extern __shared__ float shared_mem[];

    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;

    float thread_sum = 0.0f;

    for (int i = idx; i < total_elements; i += blockDim.x * gridDim.x) {
        float p_val = p[i];
        float t_val = t[i];
        thread_sum += t_val * (logf(t_val) - logf(p_val));
    }

    shared_mem[tid] = thread_sum;
    __syncthreads();

    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (tid < s) {
            shared_mem[tid] += shared_mem[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicAdd(out, shared_mem[0]);
    }
}

torch::Tensor kl_div_cuda(torch::Tensor predictions, torch::Tensor targets) {
    auto total_elements = predictions.numel();
    auto out = torch::zeros(1, predictions.options());

    int threads = 256;
    int blocks = std::min((total_elements + threads - 1) / threads, 2048);

    kl_div_kernel<<<blocks, threads, threads*sizeof(float)>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        out.data_ptr<float>(),
        total_elements
    );

    return out;
}
"""

kl_div_ext = load_inline(
    name="kl_div_ext",
    cpp_sources=kl_div_cpp,
    cuda_sources=kl_div_cuda_code,
    functions=["kl_div_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, predictions, targets):
        batch_size = predictions.size(0)
        return kl_div_ext.kl_div_cuda(predictions, targets) / batch_size
